<?php $logoToken=!empty($workspace['logo_path'])?hash_hmac('sha256',(string)App\Core\Auth::workspaceId(),(string)App\Core\Env::get('APP_KEY','')):''; $logoUrl=$logoToken?'/mail/logo/'.(int)App\Core\Auth::workspaceId().'?token='.$logoToken:''; ?><div class="page-head"><div><h1>Nastavení firmy</h1><div class="sub">Údaje firmy, které se používají v dokladech, PDF a automatických e-mailech.</div></div></div><form class="form" method="post" enctype="multipart/form-data"><div class="card"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><h3>Logo firmy</h3><p>PNG, JPG nebo SVG, maximálně 2 MB. Logo se použije v aplikaci, PDF dokladech a HTML e-mailech.</p><?php if(!empty($workspace['logo_path'])): ?><div style="display:flex;align-items:center;gap:14px;margin:12px 0"><img src="<?=\App\Core\View::e($logoUrl)?>" alt="Logo firmy" style="max-width:180px;max-height:70px;object-fit:contain;border:1px solid #e5eaf2;border-radius:12px;padding:8px;background:#fff"><span class="badge ok">Logo nahráno</span></div><?php endif; ?><div class="field"><label for="logo">Nové logo</label><input id="logo" type="file" name="logo" accept="image/png,image/jpeg,image/svg+xml"></div></div><div class="card"><div class="field"><label>Název firmy</label><input name="name" value="<?=\App\Core\View::e($workspace['name'])?>" required></div><div class="row"><div class="field"><label>IČO</label><input name="ico" value="<?=\App\Core\View::e($workspace['ico'])?>"></div><div class="field"><label>DIČ</label><input name="dic" value="<?=\App\Core\View::e($workspace['dic'])?>"></div></div><div class="row"><div class="field"><label>Ulice</label><input name="street" value="<?=\App\Core\View::e($workspace['street'])?>"></div><div class="field"><label>Město</label><input name="city" value="<?=\App\Core\View::e($workspace['city'])?>"></div></div><div class="row"><div class="field"><label>PSČ</label><input name="zip" value="<?=\App\Core\View::e($workspace['zip'])?>"></div><div class="field"><label>IBAN / bankovní účet</label><input name="bank_account" value="<?=\App\Core\View::e($workspace['bank_account'])?>" placeholder="CZ6508000000192000145399 nebo 123456789/0800" pattern="(?:CZ[0-9]{22}|[0-9]{1,10}/[0-9]{4}|[0-9]{1,10}-[0-9]{1,10}/[0-9]{4})"></div></div><div class="row"><div class="field"><label>E-mail</label><input name="email" value="<?=\App\Core\View::e($workspace['email'])?>"></div><div class="field"><label>Telefon</label><input name="phone" value="<?=\App\Core\View::e($workspace['phone'])?>"></div></div></div><div class="card"><h3>Automatické e-maily</h3><p>Odesílatel: <b><?=\App\Core\View::e($workspace['email_localpart']??'firma')?>@<?=\App\Core\View::e($mail_domain)?></b></p><div class="field"><label>Adresa před @</label><input name="email_localpart" value="<?=\App\Core\View::e($workspace['email_localpart']??'')?>" pattern="[A-Za-z0-9.-]+"></div><p><label class="switch"><input type="checkbox" name="mail_enabled" <?=!empty($workspace['mail_enabled'])?'checked':''?>><span class="track"></span><span>Posílat e-maily za mě</span></label></p><div class="row"><label class="switch"><input type="checkbox" name="mail_invoices" <?=!empty($workspace['mail_invoices'])?'checked':''?>><span class="track"></span><span>Faktury</span></label><label class="switch"><input type="checkbox" name="mail_reminders" <?=!empty($workspace['mail_reminders'])?'checked':''?>><span class="track"></span><span>Upomínky</span></label><label class="switch"><input type="checkbox" name="mail_receipts" <?=!empty($workspace['mail_receipts'])?'checked':''?>><span class="track"></span><span>Potvrzení plateb</span></label><label class="switch"><input type="checkbox" name="mail_offers" <?=!empty($workspace['mail_offers'])?'checked':''?>><span class="track"></span><span>Nabídky</span></label></div><div class="row"><label class="switch"><input type="checkbox" name="weekly_report_enabled" <?=!empty($workspace['weekly_report_enabled'])?'checked':''?>><span class="track"></span><span>Týdenní report</span></label><label class="switch"><input type="checkbox" name="monthly_report_enabled" <?=!empty($workspace['monthly_report_enabled'])?'checked':''?>><span class="track"></span><span>Měsíční report</span></label></div></div><div class="card"><h3>Číselné řady dokladů</h3><p class="sub">Nastavte vlastní prefix a číslo, od kterého bude každá řada pokračovat.</p><div class="row"><?php $seriesMap=[];foreach(($series??[]) as $sr)$seriesMap[$sr['doc_type']]=$sr;foreach(['invoice'=>'Faktury','offer'=>'Nabídky','order'=>'Objednávky','proforma'=>'Zálohové faktury','credit'=>'Dobropisy'] as $stype=>$slabel):$sr=$seriesMap[$stype]??['prefix'=>['invoice'=>'FV','offer'=>'CN','order'=>'OBJ','proforma'=>'ZAL','credit'=>'DOB'][$stype],'next_number'=>1];?><div class="card" style="box-shadow:none"><b><?=\App\Core\View::e($slabel)?></b><div class="row" style="margin-top:10px"><div class="field"><label>Prefix</label><input name="series_prefix_<?=\App\Core\View::e($stype)?>" value="<?=\App\Core\View::e($sr['prefix'])?>"></div><div class="field"><label>Další číslo</label><input type="number" min="1" name="series_next_<?=\App\Core\View::e($stype)?>" value="<?=\App\Core\View::e($sr['next_number'])?>"></div></div></div><?php endforeach;?></div></div><div class="card"><h3>GoPay pro tuto firmu</h3><p>Každá firma používá vlastní GoPay účet. Přihlašovací údaje se ukládají šifrovaně na serveru a nezobrazují se zpět.</p><?php if(!empty($gopay_connected)): ?><p><span class="badge ok">GoPay připojeno</span></p><label class="switch"><input type="checkbox" name="gopay_disconnect" value="1"><span class="track"></span><span>Odpojit GoPay účet</span></label><?php else: ?><div class="row"><div class="field"><label>GOID</label><input name="gopay_goid" inputmode="numeric"></div><div class="field"><label>Client ID</label><input name="gopay_client_id" autocomplete="off"></div></div><div class="field"><label>Client Secret</label><input type="password" name="gopay_client_secret" autocomplete="new-password"></div><?php endif; ?></div><button class="btn primary">Uložit</button></form>
